import { describe, expect, test } from '@rstest/core';

import { canonicalQuery, signTranslationRequest } from './signing.js';
import type { TranslationInput } from './types.js';

// Generated by executing signRequest in the independent official Node reference:
// https://github.com/volcengine/volcengine-nodejs-sdk/blob/157b31fea2922fcbcf5192b6c954eabd583e28d6/packages/sdk-core/src/utils/signer.ts
// Source SHA-256: 3e3fb9f5185a87ca859d92f1b208b707d297bbb9db1a13d37104412e20559c3e
// Reviewed 2026-10-22. Synthetic keys only; the reference is not a product dependency.
const input: TranslationInput = {
  text: '  Hello 世界 👋\né!  ',
  sourceLanguage: 'auto',
  targetLanguage: 'zh',
  credentials: { accessKeyId: 'fixture-ak-not-a-real-key', secretAccessKey: 'fixture-sk-not-a-real-secret' },
};

describe('independent official signing vectors', () => {
  test.each([
    {
      date: '2026-10-22T07:59:59+08:00',
      day: '20261021',
      timestamp: '20261021T235959Z',
      sourceLanguage: 'auto',
      body: '{"TargetLanguage":"zh","TextList":["  Hello 世界 👋\\né!  "]}',
      hash: '5a38f12156ce5ab227bd7d81ea2eddb3a2a1d29089726dd66356a3ca0f153b97',
      signature: '0b215d7fbcb2c9baa7f393560e38b4d2f113897a174f9329a4a8c3dd6aa86f0b',
    },
    {
      date: '2026-10-22T08:00:00+08:00',
      day: '20261022',
      timestamp: '20261022T000000Z',
      sourceLanguage: 'en',
      body: '{"TargetLanguage":"zh","TextList":["  Hello 世界 👋\\né!  "],"SourceLanguage":"en"}',
      hash: '3712daadc30226a2401411a4e1a0764c40639f8450657e080086e55147ca18a0',
      signature: 'cbae4664c0a173c1a2d778efaa1d37e4c61261864cdbc3f4982191e87fb9a3ac',
    },
  ])('matches UTC boundary $timestamp and actual body bytes', (vector) => {
    const result = signTranslationRequest({ ...input, sourceLanguage: vector.sourceLanguage }, new Date(vector.date));
    expect(result.url).toBe('https://translate.volcengineapi.com/?Action=TranslateText&Version=2020-06-01');
    expect(result.body).toBe(vector.body);
    expect(result.headers).toEqual({
      'Content-Type': 'application/json',
      'X-Date': vector.timestamp,
      'X-Content-Sha256': vector.hash,
      Authorization: `HMAC-SHA256 Credential=fixture-ak-not-a-real-key/${vector.day}/cn-north-1/translate/request, SignedHeaders=host;x-content-sha256;x-date, Signature=${vector.signature}`,
    });
    expect(result.headers).not.toHaveProperty('Host');
    expect(result.headers).not.toHaveProperty('host');
  });

  test('canonical query uses sorted keys and RFC3986 escaping from the official reference', () => {
    expect(canonicalQuery({ 'z !': "中文 /?+='()", Version: '2020-06-01', Action: 'TranslateText' })).toBe(
      'Action=TranslateText&Version=2020-06-01&z%20%21=%E4%B8%AD%E6%96%87%20%2F%3F%2B%3D%27%28%29',
    );
  });

  test('changes signatures for exact whitespace, Unicode and manual source differences', () => {
    const date = new Date('2026-10-22T00:00:00Z');
    const baseline = signTranslationRequest(input, date);
    for (const changed of [
      { ...input, text: input.text.trim() },
      { ...input, text: input.text.normalize('NFC') },
      { ...input, text: input.text.replace('\n', ' ') },
      { ...input, sourceLanguage: 'en' },
    ])
      expect(signTranslationRequest(changed, date).headers.Authorization).not.toBe(baseline.headers.Authorization);
  });
});
